package com.fakelegacy.customer;

import java.math.BigDecimal;
import java.sql.PreparedStatement;
import java.sql.Statement;
import java.sql.Timestamp;
import java.util.List;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;

@Repository
public class CustomerDao {

    @Autowired
    private JdbcTemplate jdbc;

    public Customer findById(long id) {
        List<Customer> rows = jdbc.query("select * from customers where id = ?", new CustomerRowMapper(), id);
        return rows.isEmpty() ? null : rows.get(0);
    }

    public boolean emailExists(String email) {
        Integer n = jdbc.queryForObject("select count(*) from customers where lower(email) = lower(?)", Integer.class, email);
        return n != null && n > 0;
    }

    public long count() {
        Long n = jdbc.queryForObject("select count(*) from customers", Long.class);
        return n == null ? 0L : n;
    }

    public long insert(Customer c) {
        KeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "insert into customers (email, customer_type, company_name, vat_number, registered_at, blacklisted, "
                            + "tier_override, loyalty_points, credit_limit, credit_outstanding) values (?,?,?,?,?,?,?,?,?,?)",
                    Statement.RETURN_GENERATED_KEYS);
            ps.setString(1, c.getEmail());
            ps.setString(2, c.getType());
            ps.setString(3, c.getCompanyName());
            ps.setString(4, c.getVatNumber());
            ps.setTimestamp(5, Timestamp.valueOf(c.getRegisteredAt()));
            ps.setBoolean(6, c.isBlacklisted());
            ps.setString(7, c.getTierOverride());
            ps.setInt(8, c.getLoyaltyPoints());
            ps.setBigDecimal(9, c.getCreditLimit());
            ps.setBigDecimal(10, c.getCreditOutstanding());
            return ps;
        }, keys);
        Number key = (Number) keys.getKeys().get("ID");
        return key.longValue();
    }

    public void setBlacklisted(long id, boolean value) {
        jdbc.update("update customers set blacklisted = ? where id = ?", value, id);
    }

    public boolean tryConsumeCredit(long id, BigDecimal amount) {
        int rows = jdbc.update("update customers set credit_outstanding = credit_outstanding + ? "
                + "where id = ? and credit_limit - credit_outstanding >= ?", amount, id, amount);
        return rows == 1;
    }

    // amount is negative here
    public boolean tryReleaseCredit(long id, BigDecimal amount) {
        int rows = jdbc.update("update customers set credit_outstanding = credit_outstanding + ? "
                + "where id = ? and credit_outstanding + ? >= 0", amount, id, amount);
        return rows == 1;
    }
}
